from pathlib import Path
import os,shutil
r=Path(os.getenv('ATLAS_R4_ROOT',str(Path(__file__).resolve().parent.parent)));src=Path(os.getenv('ATLAS_R3_SITE',str(r.parent/'atlas_d_engineering_r3/live')));site=r/'site';site.mkdir(exist_ok=True)
for f in ['runtime.js','THIRD_PARTY_LICENSE.txt','style.css']:shutil.copy(src/f,site/f)
