s=s.replace('Upper pavilions are floodable, surface-only spaces—not ordinary yacht rooms underwater.','Upper rooms have been replaced by open leisure canopies. Only unoccupied exterior hardware folds; the proposed dry core stays fixed.')
s=s.replace("['Stow surface fittings','Guardrails and mast fold. Pool covers are fairings, not pressure seals.']","['Transform the exterior','Daybeds and radar fold; constant-length scissor supports lower the two canopy roofs. Side terraces fold in; the aft fairing closes.']")
s=s.replace('if(playing){pose(p+direction*dt/42);if(p>=1||p<=0)','if(playing){pose(p+direction*dt/42);if(stopAt!==null&&p>=stopAt){pose(stopAt);playing=false;stopAt=null;ui()}if(p>=1||p<=0)')
s=s.replace('function reset(){playing=false;','function reset(){stopAt=null;playing=false;')
s=s.replace("$('#play').onclick=()=>{","$('#play').onclick=()=>{stopAt=null;")
s=s.replace("$('#force').innerHTML=(dp*100).toFixed(0)+' <small>kN</small>';","$('#roofdrop').innerHTML=(5.16*smooth(.28,.54,p)).toFixed(2)+' <small>m</small>';")
s=s.replace("$('#play').textContent=playing?'Pause':p>=1?'Replay dive':p===0?'Start dive':'Continue';","$('#play').textContent=playing?'Pause':p>=1?'Replay dive':p>=.60?'Dive':'Full sequence';$('#transform').textContent=playing&&stopAt!==null?'Transforming…':'Transform only';if(!playing&&Math.abs(p-.62)<.003){$('#stage').textContent='Dive-ready silhouette · held above water';$('#detail').textContent='Compare the lower roofline, folded terraces and closed aft deck. The same hull and pressure core are still here.';}")
insert="""
$('#transform').onclick=()=>{reset();if(xray)setXray(false);setView('profile');stopAt=.62;play(1)};
$('#compare').onclick=()=>{const next=p>.3?0:.62;reset();if(xray)setXray(false);pose(next);setView('profile')};
"""
s=s.replace('setView();\nfunction fail(e)',insert+'\nsetView();\nfunction fail(e)')
s=s.replace('renderer.shadowMap.needsUpdate=true;}','renderer.shadowMap.needsUpdate=!playing;}')
