h=(src/'index.html').read_text().replace('REVISION 03','REVISION 04').replace('/ 03 — Pressure Boundary Study','/ 04 — Transforming Exterior')
h=h.replace('A yacht above.<br>A pressure vessel within.','One vessel.<br>A visibly different silhouette.').replace('Continuous-vessel study','Articulated exterior study')
h=h.replace('<label>LOAD / 1 m²*</label><strong id="force">0 <small>kN</small></strong>','<label>CANOPY ROOF DROP</label><strong id="roofdrop">0 <small>m</small></strong>')
